static uint16_t packed[GLYPH_COUNT][QDOS_FONT_H];
static bool packed_ready;

static void pack_glyphs(void) {
	for (int i = 0; i < GLYPH_COUNT; i++) {
		for (int y = 0; y < QDOS_FONT_H; y++) {
			uint16_t bits = 0;
			for (int x = 0; x < QDOS_FONT_W; x++) {
				if (GLYPHS[i][y][x] == '#')
					bits |= (uint16_t)(1u << x);
			}
			packed[i][y] = bits;
		}
	}
	packed_ready = true;
}

uint16_t qdos_font_row(char ch, int row) {
	if (row < 0 || row >= QDOS_FONT_H)
		return 0;

	const unsigned char c = (unsigned char)ch;
	if (c < FIRST_CHAR || c > LAST_CHAR)
		return 0;

	if (!packed_ready)
		pack_glyphs();

	return packed[c - FIRST_CHAR][row];
}
